package com.muhabbet.app

/**
 * Whether this binary is a debuggable build, resolved from the platform's own build type rather
 * than a constant someone has to remember. Read through `BuildInfo.DEBUG`; `BuildInfo` itself is
 * generated by `:mobile:composeApp:generateBuildInfo` from the single version source (#863), and
 * this is the one part of it that is a fact of the platform, not of the version.
 */
internal expect fun isDebugBuild(): Boolean
